 [string[]]
 $verb = '*'
)
begin {
 $allVerbs = [PSObject].Assembly.GetTypes() |
 Where-Object {$_.Name -match '^Verbs.'} |
 Get-Member -type Properties -static |
 Select-Object @{
 Name='Verb'
 Expression = {$_.Name}
 }, @{
 Name='Group'
 Expression = {
 $str = "$($_.TypeName)"
 $str.Substring($str.LastIndexOf('Verbs') + 5)
 }
 }
}
process {
 foreach ($v in $verb) {
 $allVerbs | Where-Object { $_.Verb -like $v }
 }
}
